def _render_login_branding() -> None:
    # Logos and all four campus labels live in the approved left-side artwork.
    # This HTML contains only real title text, avoiding double-rendered logos.
    st.markdown("""
    <div class="jk-exec-title">
      <h1>Executive Daily<br/>Admissions Dashboard</h1>
      <div class="jk-title-glow" aria-hidden="true"></div>
    </div>
    """, unsafe_allow_html=True)


def _render_login_form() -> tuple[bool, str, str, object]:
    # Only real Streamlit controls. No screenshot-generated fake fields.
    _, right = st.columns([1.02, 0.98], gap="small", vertical_alignment="top")
    with right:
        with st.form("jaipuria_login_form", clear_on_submit=False):
            username = st.text_input("Username", key="login_username", placeholder="Enter Username")
            password = st.text_input("Password", key="login_password", type="password", placeholder="Enter Password")
            submitted = st.form_submit_button("Log in  →", use_container_width=True)
        feedback = st.empty()
    return submitted, username, password, feedback


def _auth_config() -> tuple[str, str]:
    try:
        configured = "dashboard_auth" in st.secrets
    except Exception:
        configured = False
    if not configured:
        st.error("Dashboard login is not configured. Add [dashboard_auth] in Streamlit Secrets.")
        st.stop()

    cfg = st.secrets["dashboard_auth"]
    try:
        expected_username = str(cfg["username"])
        expected_password = str(cfg["password"])
    except Exception:
        st.error("Dashboard login configuration is incomplete. Check Streamlit Secrets.")
        st.stop()
    return expected_username, expected_password


def require_login(session_hours: int = 4) -> None:
    """Authenticate before importing dashboard data, removing the login UI immediately on success."""
    _hide_streamlit_chrome()

    expires_at = st.session_state.get("auth_expires_at")
    authenticated = bool(st.session_state.get("authenticated", False))

    if authenticated and expires_at:
        try:
            expiry = datetime.fromisoformat(expires_at)
            if datetime.now() < expiry:
                return
        except (ValueError, TypeError):
            pass

    st.session_state["authenticated"] = False
    st.session_state.pop("auth_expires_at", None)

    # All visible login elements live in one replaceable container. On a
    # successful login it is removed before the dashboard renders, avoiding
    # the ghosted/disabled login form during an expensive initial Sheets fetch.
    login_host = st.empty()
    with login_host.container():
        _render_form_css()
        _render_login_branding()
        expected_username, expected_password = _auth_config()
        submitted, entered_username, entered_password, feedback = _render_login_form()

        if submitted:
            username_ok = compare_digest(
                entered_username.strip().encode("utf-8"),
                expected_username.encode("utf-8"),
            )
            password_ok = compare_digest(
                entered_password.encode("utf-8"),
                expected_password.encode("utf-8"),
            )
            if username_ok and password_ok:
                st.session_state["authenticated"] = True
                st.session_state["auth_expires_at"] = (
                    datetime.now() + timedelta(hours=session_hours)
                ).isoformat()
                # A clean rerun is essential: don't let login-only CSS/DOM
                # persist into the authenticated page's first render.
                login_host.empty()
                st.rerun()
            else:
                feedback.error("Invalid username or password. Please try again.", icon="🔒")

        if not st.session_state["authenticated"]:
            st.markdown(
                '<div class="jk-login-note">Jaipuria Institute of Management · Authorized access only</div>',
                unsafe_allow_html=True,
            )

    # Invalid or no credentials: stop before any dashboard code executes.
    st.stop()


def logout() -> None:
    st.session_state["authenticated"] = False
    st.session_state.pop("auth_expires_at", None)
    st.rerun()
